// ================= EMMA POC CONFIG (edit here) =================
const CFG = {
  ALLOWLIST: ['__SET_TEAM_NUMBERS__'],      // E.164 team numbers allowed to talk to the POC
  POC_LINE: '__SET_POC_LINE__',             // the Sendblue line Emma answers on
  WEBHOOK_SECRET: '__SET_WEBHOOK_SECRET__', // Sendblue webhook secret (value-matched across headers)
  ASSISTANT_NAME: 'Emma',
  COMPANY_NAME: 'Big Think Capital'
};
// ===============================================================
function normalize(raw) { if (!raw) return null; const d = String(raw).trim().replace(/[^\d+]/g, ''); if (/^\+\d{8,15}$/.test(d)) return d; const b = d.replace(/\D/g, ''); if (b.length === 10) return '+1' + b; if (b.length === 11 && b.startsWith('1')) return '+' + b; return null; }
const headers = $json.headers || {};
const body = $json.body || {};
// Secret check: Sendblue includes the configured secret in a request header; the exact
// header name varies, so match the VALUE across headers (constant-time per header).
const secretOk = CFG.WEBHOOK_SECRET.length > 0 && Object.values(headers).some(v => {
  const s = String(v); if (s.length !== CFG.WEBHOOK_SECRET.length) return false;
  let d = 0; for (let i = 0; i < s.length; i++) d |= s.charCodeAt(i) ^ CFG.WEBHOOK_SECRET.charCodeAt(i); return d === 0;
});
const from = normalize(body.from_number || body.number);
const to = normalize(body.to_number);
const content = String(body.content || '').trim();
const handle = body.message_handle || null;
const isOutbound = body.is_outbound === true || String(body.is_outbound) === 'true';
// Deterministic drop reasons — everything not for the POC exits silently.
let drop = null;
if (!secretOk) drop = 'bad_secret';
else if (isOutbound) drop = 'outbound_echo';
else if (!handle) drop = 'no_handle';
else if (!from || !CFG.ALLOWLIST.includes(from)) drop = 'not_allowlisted';
else if (!to || to !== CFG.POC_LINE) drop = 'wrong_line';
else if (!content && !body.media_url) drop = 'empty';
// Dedupe on message_handle via workflow static data (POC-grade).
if (!drop) {
  const sd = $getWorkflowStaticData('global');
  sd.handles = sd.handles || [];
  if (sd.handles.includes(handle)) drop = 'duplicate';
  else { sd.handles.push(handle); if (sd.handles.length > 300) sd.handles = sd.handles.slice(-200); }
}
// Deterministic opt-out BEFORE the model (POC still honors STOP absolutely).
const NEG = /(don'?t|do not|never|please don'?t|no need to)\s+(?:\w+\s+){0,3}$/i;
const PHRASES = ['stop','unsubscribe','cancel','opt out','remove me','stop texting','stop messaging me','do not text me',"don't text me",'no more texts','take me off your list'];
const lower = content.toLowerCase();
const stripped = lower.replace(/[!.?,;:'"()\s]+$/g, '').replace(/^[!.?,;:'"()\s]+/g, '');
let optOut = false;
for (const p of PHRASES) { if (stripped === p) { optOut = true; break; } const i = lower.indexOf(p); if (i >= 0 && p.includes(' ') && !NEG.test(lower.slice(0, i))) { optOut = true; break; } }
let route = drop ? 'drop' : optOut ? 'opt_out' : 'ai';
// Conversation memory (per-contact, last 12 turns) from static data.
let memory = [];
if (route === 'ai') {
  const sd = $getWorkflowStaticData('global');
  sd.convos = sd.convos || {};
  memory = (sd.convos[from] || []).slice(-12);
}
if (route === 'opt_out') {
  const sd = $getWorkflowStaticData('global');
  sd.optedOut = sd.optedOut || [];
  if (!sd.optedOut.includes(from)) sd.optedOut.push(from);
}
if (route === 'ai') { const sd = $getWorkflowStaticData('global'); if ((sd.optedOut || []).includes(from)) route = 'drop'; }
console.log(JSON.stringify({ poc: 'emma', route, drop_reason: drop, handle, ts: new Date().toISOString() }));
return [{ json: { route, from, to, content, handle, memory, cfg: { ASSISTANT_NAME: CFG.ASSISTANT_NAME, COMPANY_NAME: CFG.COMPANY_NAME, POC_LINE: CFG.POC_LINE } } }];

const gate = $('POC Gate (allowlist + dedupe + opt-out)').first().json;
let reply = null, handoff = false;
try {
  const resp = $input.first().json;
  const raw = resp.content && resp.content[0] && resp.content[0].text;
  let parsed = null;
  try { parsed = JSON.parse(raw); } catch { const s = raw.indexOf('{'), e = raw.lastIndexOf('}'); if (s >= 0 && e > s) { try { parsed = JSON.parse(raw.slice(s, e + 1)); } catch {} } }
  if (parsed && typeof parsed.reply_text === 'string' && parsed.reply_text.trim()) {
    reply = parsed.reply_text.trim().slice(0, 900);
    handoff = parsed.request_human_handoff === true;
  }
} catch (e) { /* fall through to fallback */ }
// Output guardrails: block forbidden claims even in POC.
if (reply && /(guarantee(d)? (approval|rate|funding|amount)|you (are|'re) approved|we are a bank)/i.test(reply)) reply = null;
if (!reply) reply = "Thanks for your message! I want to make sure you get an accurate answer, so a member of our team will follow up with you here.";
// Update conversation memory.
const sd = $getWorkflowStaticData('global');
sd.convos = sd.convos || {};
const mem = sd.convos[gate.from] || [];
mem.push({ role: 'user', text: gate.content.slice(0, 500) });
mem.push({ role: 'assistant', text: reply.slice(0, 500) });
sd.convos[gate.from] = mem.slice(-16);
return [{ json: { to: gate.from, from_line: gate.cfg.POC_LINE, reply, handoff } }];

const r = $input.first().json;
console.log(JSON.stringify({ poc: 'emma', action: 'sent', status: r.status || null, handle: r.message_handle || null, ts: new Date().toISOString() }));
return [{ json: { done: true } }];
